{
  "name": "视频文件帧采集源",
  "name_en": "Video File Capture",
  "manufacturer": "",
  "description": "这是一个非物理的软件视频源组件，用于从视频文件中读取并持续提供图像帧。它可连接到文件路径、在后台线程中连续抓取最新帧，并用于实验视频回放、图像处理流程测试或在没有真实相机时模拟视频输入。",
  "description_en": "This is a non-physical software video source component that reads and serves image frames from a video file. It can connect to a file path, continuously capture frames in a background thread, and is used for experiment video playback, image-processing pipeline testing, or simulating camera input when no real camera is present.",
  "actions": [
    {
      "action_name": "auto-start_async",
      "description": "启动后台线程，持续从视频文件捕获帧。",
      "description_en": "Start a background thread to continuously capture frames from the video file."
    },
    {
      "action_name": "auto-stop",
      "description": "停止后台帧捕获线程。",
      "description_en": "Stop the background frame capture thread."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到视频文件源。",
      "description_en": "Connect to the video file source."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与视频文件源的连接。",
      "description_en": "Disconnect from the video file source."
    },
    {
      "action_name": "auto-set_exposure",
      "description": "设置曝光。",
      "description_en": "set exposure"
    },
    {
      "action_name": "auto-set_gain",
      "description": "设置增益。",
      "description_en": "set gain"
    },
    {
      "action_name": "auto-enable_auto_exposure",
      "description": "启用或禁用自动曝光（对视频文件源不适用）。",
      "description_en": "Enable or disable auto exposure (not applicable to video file sources)."
    },
    {
      "action_name": "auto-set_frame_size",
      "description": "设置帧尺寸（对视频文件源不适用）。",
      "description_en": "Set frame size (not applicable to video file sources)."
    }
  ],
  "tag_hints": [
    "video file playback",
    "camera simulation",
    "background frame capture",
    "frame replay",
    "image pipeline testing",
    "media source"
  ]
}

